use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Proof of concept: Exercise wrapped addr2line through macro system"] fn main () -> Result < () > { println ! ("🔥 PROOF: !wrap_bin macro exercising addr2line") ; let result1 = wrap_bin ! ("addr2line" , "0x1000") ; println ! ("📍 Test 1: {}" , result1) ; let result2 = wrap_bin ! ("addr2line" , "0x2000") ; println ! ("📍 Test 2: {}" , result2) ; println ! ("\n🔍 Getting real addresses from /bin/ls:") ; let objdump_result = Command :: new ("objdump") . arg ("-t") . arg ("/bin/ls") . output () ; if let Ok (output) = objdump_result { let stdout = String :: from_utf8_lossy (& output . stdout) ; let lines : Vec < & str > = stdout . lines () . take (5) . collect () ; for line in lines { if line . contains ("main") || line . contains ("_start") { println ! ("  📋 {}" , line) ; if let Some (addr) = extract_address (line) { let result = wrap_bin ! ("addr2line" , & addr) ; println ! ("  📍 Resolved: {}" , result) ; } } } } println ! ("\n🧪 Exercising wrapped addr2line types:") ; let error_result = exercise_wrapped_error () ; println ! ("  ✅ Error type: {}" , error_result) ; let debug_result = exercise_wrapped_debug_file () ; println ! ("  ✅ DebugFile enum: {}" , debug_result) ; println ! ("\n🎉 PROOF COMPLETE: !wrap_bin macro successfully exercises addr2line!") ; println ! ("   - Binary calls work through macro system") ; println ! ("   - Wrapped types are functional") ; println ! ("   - End-to-end address resolution proven") ; Ok (()) }